/bin/bash -lc "python3 -u - <<'PY'
import socket, struct

TYPE_NAMES = {1:'A',28:'AAAA',5:'CNAME',15:'MX',2:'NS',12:'PTR',6:'SOA',33:'SRV',16:'TXT',257:'CAA',13:'HINFO',35:'NAPTR',44:'SSHFP',52:'TLSA',29:'LOC'}

def enc_name(name):
    out = b''
    for label in name.rstrip('.').split('.'):
        if label:
            out += bytes([len(label)]) + label.encode()
    return out + b'\\x00'

def skip_name(data, offset):
    while True:
        l = data[offset]
        offset += 1
        if l == 0:
            return offset
        if l & 0xC0 == 0xC0:
            return offset + 1
        offset += l

def parse_name(data, offset):
    labels = []
    jumped = False
    orig = offset
    while True:
        l = data[offset]
        if l == 0:
            offset += 1
            break
        if l & 0xC0 == 0xC0:
            ptr = ((l & 0x3F) << 8) | data[offset+1]
            if not jumped:
                orig = offset + 2
                jumped = True
            offset = ptr
            continue
        offset += 1
        labels.append(data[offset:offset+l].decode())
        offset += l
    return '.'.join(labels) + '.', (orig if jumped else offset)

sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
sock.bind(('127.0.0.1', 5303))
print('READY', flush=True)
while True:
    data, addr = sock.recvfrom(4096)
    tid = data[:2]
    flags_in = struct.unpack('"'!H'"', data[2:4])[0]
    qdcount = struct.unpack('"'!H'"', data[4:6])[0]
    off = 12
    if qdcount "'!= 1:
        continue
    qname, off2 = parse_name(data, off)
    off = off2
    qtype, qclass = struct.unpack('"'"'!HH'"', data[off:off+4])
    off += 4
    question = data[12:off]
    print('REQ', TYPE_NAMES.get(qtype, qtype), qname, data.hex(), flush=True)
    flags = 0x8180 | (flags_in & 0x0100) | (flags_in & 0x0020) | (flags_in & 0x0010)
    answer_rdata = b''
    ttl = 123
    atype = qtype
    if qtype == 1:
        answer_rdata = bytes([1,2,3,4])
    elif qtype == 28:
        answer_rdata = bytes.fromhex('20010db8000000000000000000000001')
    elif qtype == 5:
        answer_rdata = enc_name('alias.example.net.')
    elif qtype == 15:
        answer_rdata = struct.pack('"'!H'"', 10) + enc_name('mail.example.net.')
    elif qtype == 2:
        answer_rdata = enc_name('ns1.example.net.')
    elif qtype == 12:
        answer_rdata = enc_name('ptr.example.net.')
    elif qtype == 6:
        answer_rdata = enc_name('ns1.example.net.') + enc_name('hostmaster.example.net.') + struct.pack('"'!IIIII'"', 2023081501, 7200, 3600, 1209600, 600)
    elif qtype == 33:
        answer_rdata = struct.pack('"'!HHH'"', 1, 2, 443) + enc_name('srv.example.net.')
    elif qtype == 16:
        parts = [b'hello', b'world']
        answer_rdata = b''.join(bytes([len(p)]) + p for p in parts)
    elif qtype == 257:
        answer_rdata = bytes([0, 0]) + b'issue'
    elif qtype == 13:
        answer_rdata = bytes([5]) + b'Intel' + bytes([5]) + b'Linux'
    elif qtype == 35:
        answer_rdata = struct.pack('"'!HH'"', 100, 10) + bytes([1]) + b'U' + bytes([7]) + b'E2U+sip' + enc_name('"'!''^.*$!sip:info@example.net!'"')
    elif qtype == 44:
        answer_rdata = bytes([1,1]) + bytes.fromhex('1234567890abcdef')
    elif qtype == 52:
        answer_rdata = bytes([3,1,1]) + bytes.fromhex('00112233445566778899aabbccddeeff')
    elif qtype == 29:
        # simplistic LOC from RFC 1876 example-ish values
        answer_rdata = bytes([0,0x12,0x13,0x16]) + struct.pack('"'!III'"', 0x80000000 + 37*3600*1000, 0x80000000 - 122*3600*1000, 10000000)
    else:
        atype = qtype
        answer_rdata = bytes([1,2,3,4,5])
    answer = b'\\xc0\\x0c' + struct.pack('"'!H'"', atype) + struct.pack('"'!H'"', qclass) + struct.pack('"'!I'"', ttl) + struct.pack('"'!H'"', len(answer_rdata)) + answer_rdata
    resp = tid + struct.pack('"'!H'"', flags) + b'\\x00\\x01\\x00\\x01\\x00\\x00\\x00\\x00' + question + answer
    sock.sendto(resp, addr)
    print('RESP', resp.hex(), flush=True)
PY"

